```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecureConfig {
  constructor() {
    this.secrets = {};
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  }

  async loadSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      // Parse the secret string
      const secret = JSON.parse(response.SecretString);

      // Cache with expiration
      this.secrets[secretName] = {
        data: secret,
        expires: Date.now() + 300000 // 5 minutes
      };

      return secret;
    } catch (error) {
      console.error(`Failed to load secret ${secretName}:`, error);
      throw new Error('Secret configuration error');
    }
  }

  async getSecret(secretName, key) {
    // Check cache
    const cached = this.secrets[secretName];
    if (cached && cached.expires > Date.now()) {
      return cached.data[key];
    }

    // Load fresh secret
    const secret = await this.loadSecret(secretName);
    return secret[key];
  }
}

// Usage in your app
const secureConfig = new SecureConfig();

app.get('/database/query', async (req, res) => {
  try {
    const dbUrl = await secureConfig.getSecret('production/database', 'DATABASE_URL');

    // Use the secret securely - never log it!
    const connection = await createConnection(dbUrl);
    // ... database operations

  } catch (error) {
    logger.error('Database operation failed', { error: error.message });
    res.status(500).json({ error: 'Operation failed' });
  }
});
```

#### **Option 2: HashiCorp Vault** (Cloud-agnostic)

```javascript
const axios = require('axios');
constNodeCache = require('node-cache');

class VaultSecrets {
  constructor() {
    this.cache = new NodeCache({ stdTTL: 300 }); // 5 minute TTL
    this.vaultToken = process.env.VAULT_TOKEN; // This comes from IAM role, not .env!
    this.vaultAddr = process.env.VAULT_ADDR || 'https://vault.company.com';
  }

  async getSecret(path) {
    // Check cache first
    const cached = this.cache.get(path);
    if (cached) return cached;

    try {
      const response = await axios.get(
        `${this.vaultAddr}/v1/secret/data/${path}`,
        {
          headers: { 'X-Vault-Token': this.vaultToken },
          timeout: 5000
        }
      );

      const secret = response.data.data.data;
      this.cache.set(path, secret);

      return secret;
    } catch (error) {
      logger.error('Vault access error', { path, error: error.message });
      throw new Error('Secret access denied');
    }
  }
}

const vault = new VaultSecrets();

// Usage
app.post('/payment', async (req, res) => {
  const stripeKeys = await vault.getSecret('production/stripe');
  const stripe = require('stripe')(stripeKeys.STRIPE_SECRET_KEY);
  // ... payment processing
});
```

