```javascript
// config/secrets.js
class SecretManager {
  constructor() {
    this.environment = process.env.NODE_ENV || 'development';
    this.loader = this.getLoader();
  }

  getLoader() {
    switch(this.environment) {
      case 'production':
        // Production: Use AWS Secrets Manager or Vault
        return require('./production-secret-loader');

      case 'staging':
        // Staging: Use dedicated staging secrets manager
        return require('./staging-secret-loader');

      case 'development':
        // Development: Use local secure vault or throw error
        // NEVER allow .env files even in development
        throw new Error('Development secrets must be loaded from local vault');

      case 'test':
        // Test: Use mock secrets service
        return require('./test-secret-loader');

      default:
        throw new Error(`Unsupported environment: ${this.environment}`);
    }
  }

  async getSecret(key) {
    try {
      const secret = await this.loader.getSecret(key);

      // Audit log (never log the secret value!)
      logger.info('Secret accessed', { 
        key, 
        environment: this.environment,
        user: getCurrentUser() // If applicable
      });

      return secret;
    } catch (error) {
      logger.error('Secret access failed', { 
        key, 
        environment: this.environment,
        error: error.message 
      });
      throw new Error('Configuration error');
    }
  }
}

module.exports = new SecretManager();
```

