      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'JWT_SECRET'
    ];

    requiredSecrets.forEach(secret => {
      if (!process.env[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }
    });

    // Validate specific formats
    if (!process.env.DATABASE_URL.startsWith('postgres://')) {
      throw new Error('DATABASE_URL must be a valid PostgreSQL connection string');
    }

    // Check for obvious hardcoded secrets (like "password123", "admin", etc.)
    const weakPatterns = /(password123|admin|123456|secret|key)/i;
    Object.entries(process.env).forEach(([key, value]) => {
      if (key.includes('KEY') || key.includes('SECRET') || key.includes('PASSWORD')) {
        if (weakPatterns.test(value)) {
          logger.warn(`Weak secret detected in ${key}`);
        }
      }
    });
  }

  // Safe getter methods that don't expose secrets
  getDatabaseConfig() {
    return { url: this.secrets.database.url };
  }

  getAwsCredentials() {
    return {
      accessKeyId: this.secrets.aws.accessKeyId,
      secretAccessKey: this.secrets.aws.secretAccessKey
    };
  }
}

module.exports = new SecretsManager();
```

#### **3. App.js Doesn't Load Secrets Properly**
**Issue**: `app.js` shows no sign of loading environment variables

**Fix: Add proper dotenv loading with security checks:**
```javascript
// Add at the top of app.js BEFORE any other imports
const fs = require('fs');
const path = require('path');

// Secure dotenv loading
function loadEnvironment() {
  // Determine which .env file to load
  const nodeEnv = process.env.NODE_ENV || 'development';
  const envFile = `.env.${nodeEnv}`;

  // Check if .env file exists (but don't load in production!)
  if (fs.existsSync(path.join(process.cwd(), envFile))) {
    if (nodeEnv === 'production') {
      console.warn('WARNING: Loading secrets from .env files in production is insecure!');
      console.warn('Use a secrets manager instead.');
      // Don't load in production - require proper secrets management
      throw new Error('Secrets must be provided via environment variables in production');
    }

    // Only load dotenv in non-production environments
    const dotenv = require('dotenv');
    const result = dotenv.config({ path: envFile });

    if (result.error) {
      throw new Error(`Failed to load ${envFile}: ${result.error.message}`);
    }

    console.log(`Loaded environment from ${envFile}`);
  }
}

// Load environment before any other code
loadEnvironment();

// Then initialize express
const express = require('express');
const app = express();
```

#### **4. Secrets Are Accessible in Memory**
**Issue**: Once loaded, secrets remain in process memory and could be leaked

**Recommendation**: Use secure memory handling:
```javascript
const secrets = require('./config/secrets');

// In your routes/controllers
