    status: 'ok', 
    timestamp: new Date().toISOString(),
    // DON'T do this:
    // config: secrets.getDatabaseConfig() // NEVER expose secrets
  });
});
```

#### **5. No Secret Rotation Mechanism**
**Issue**: Static secrets become less secure over time

**Recommendation**: Implement secret rotation:
```javascript
// config/secretRotation.js
class SecretRotationManager {
  constructor() {
    this.secretCache = new Map();
    this.rotationIntervals = new Map();
  }

  async rotateSecret(secretName, provider) {
    try {
      console.log(`Rotating secret: ${secretName}`);

      // Get new secret from provider (AWS Secrets Manager, HashiCorp Vault, etc.)
      const newSecret = await provider.generateNewSecret(secretName);

      // Update the secret
      process.env[secretName] = newSecret;

      // Clear any cached values
      this.secretCache.delete(secretName);

      console.log(`Successfully rotated secret: ${secretName}`);

      // Log rotation event (without exposing the secret)
      logger.info({
        event: 'secret_rotated',
        secret_name: secretName,
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      logger.error({
        event: 'secret_rotation_failed',
        secret_name: secretName,
        error: error.message
      });
      throw error;
    }
  }

  scheduleRotation(secretName, intervalMs, provider) {
    if (this.rotationIntervals.has(secretName)) {
      clearInterval(this.rotationIntervals.get(secretName));
    }

    const interval = setInterval(() => {
      this.rotateSecret(secretName, provider).catch(error => {
        console.error(`Failed to rotate ${secretName}:`, error);
      });
    }, intervalMs);

    this.rotationIntervals.set(secretName, interval);
    console.log(`Scheduled rotation for ${secretName} every ${intervalMs}ms`);
  }
}

module.exports = new SecretRotationManager();
```

