```javascript
// config/awsSecretsManager.js
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

class AwsSecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.secretCache = new Map();
    this.maxAge = 5 * 60 * 1000; // 5 minutes cache
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.secretCache.get(secretName);
    if (cached && (Date.now() - cached.timestamp) < this.maxAge) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: "AWSCURRENT"
      });

      const data = await this.client.send(command);

      let secretValue;
      if ('SecretString' in data) {
        secretValue = data.SecretString;
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Cache the secret
      this.secretCache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      console.log(`Successfully retrieved secret: ${secretName}`);
      return secretValue;

    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getDatabaseConfig() {
    const secret = await this.getSecret('prod/database');
    return JSON.parse(secret);
  }

  async getStripeSecret() {
    return await this.getSecret('prod/stripe-secret-key');
  }
}

module.exports = new AwsSecretsManager();
```

