## 🔐 Proper Secrets Management Architecture

Here's a complete secure implementation:

```javascript
require('dotenv').config(); // Only in development, never in production

const express = require('express');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const winston = require('winston');

const app = express();

// 1. Secure secrets loading
class SecureSecretsManager {
  constructor() {
    if (process.env.NODE_ENV === 'production') {
      this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    }
    this.secrets = {};
  }

  async loadAllSecrets() {
    if (process.env.NODE_ENV !== 'production') {
      // Development: Use secure local config only
      this.secrets = this.loadDevelopmentSecrets();
      return;
    }

    // Production: Load from AWS Secrets Manager
    const secrets = [
      'prod/database/credentials',
      'prod/stripe/key',
      'prod/anthropic/api-key'
    ];

    for (const secretName of secrets) {
      try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await this.client.send(command);
        this.secrets[secretName] = JSON.parse(response.SecretString);
      } catch (error) {
        throw new Error(`Failed to load secret: ${secretName}`);
      }
    }
  }

  loadDevelopmentSecrets() {
    // Only for local development with non-sensitive defaults
    return {
      DATABASE_URL: process.env.DATABASE_URL || 'postgres://localhost/dev',
      LOG_LEVEL: process.env.LOG_LEVEL || 'debug'
      // NEVER include real secrets here
    };
  }

  getSecret(key) {
    return this.secrets[key];
  }
}

// 2. Initialize secrets before starting server
const secretsManager = new SecureSecretsManager();

async function startServer() {
  try {
    await secretsManager.loadAllSecrets();

    // Verify critical secrets loaded
    if (!secretsManager.getSecret('prod/database/credentials')) {
      throw new Error('Database credentials not loaded');
    }

    // Start server only after secrets are loaded
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

// 3. Secure usage in routes
app.post('/payment', async (req, res) => {
  try {
    const stripeSecret = secretsManager.getSecret('prod/stripe/key');
    // Use stripe SDK with secret
    const payment = await stripe.paymentIntents.create({
      amount: req.body.amount,
      currency: 'usd',
    }, { apiKey: stripeSecret });

    res.json({ success: true, paymentId: payment.id });
  } catch (error) {
    securityLogger.error('Payment processing error', { error: error.message });
    res.status(500).json({ error: 'Payment failed' });
  }
});

// 4. Security monitoring for secrets access
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security-audit.log' }),
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});

startServer().catch(console.error);
