## Recommended Solutions with Code Examples

### Option 1: AWS Secrets Manager (Recommended for AWS environments)

**1. Install AWS SDK:**
```bash
npm install @aws-sdk/client-secrets-manager
```

**2. Create a secrets manager module (`secrets.js`):**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const client = new SecretsManagerClient({ region: 'us-east-1' });

let cachedSecrets = null;

async function getSecrets() {
  if (cachedSecrets) {
    return cachedSecrets;
  }

  try {
    const command = new GetSecretValueCommand({
      SecretId: 'prod/myapp/secrets'
    });

    const response = await client.send(command);

    if (response.SecretString) {
      cachedSecrets = JSON.parse(response.SecretString);
      return cachedSecrets;
    }
  } catch (error) {
    console.error('Error retrieving secrets:', error);
    throw error;
  }
}

module.exports = {
  getSecrets,
  getSecret: async (key) => {
    const secrets = await getSecrets();
    return secrets[key];
  }
};
```

**3. Use in your application (`app.js`):**
```javascript
