```

**2. Create Vault configuration (`vault.js`):**
```javascript
const axios = require('axios');

class VaultManager {
  constructor() {
    this.client = axios.create({
      baseURL: process.env.VAULT_ADDR || 'http://localhost:8200',
      headers: {
        'X-Vault-Token': process.env.VAULT_TOKEN
      }
    });
  }

  async getSecret(path) {
    try {
      const response = await this.client.get(`/v1/secret/data/${path}`);
      return response.data.data.data;
    } catch (error) {
      console.error('Vault error:', error.response?.data || error.message);
      throw error;
    }
  }
}

module.exports = VaultManager;
```

**3. Application usage:**
