### Option 4: Secure In-Memory Caching

**Create a secure secrets cache (`secure-cache.js`):**
```javascript
class SecureSecretsCache {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  async initialize(getSecretsFn) {
    if (this.initialized) return;

    const secrets = await getSecretsFn();
    for (const [key, value] of Object.entries(secrets)) {
      this.secrets.set(key, value);
    }

    this.initialized = true;
    // Freeze to prevent modification
    Object.freeze(this.secrets);
  }

  get(key) {
    if (!this.initialized) {
      throw new Error('Secrets cache not initialized');
    }
    return this.secrets.get(key);
  }

  // No method to clear or modify secrets after initialization
}

module.exports = new SecureSecretsCache();
```

