```javascript
// Install AWS SDK
// npm install @aws-sdk/client-secrets-manager

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsManager = new SecretsManagerClient({ region: 'us-east-1' });

async function getSecret(secretName) {
  try {
    const command = new GetSecretValueCommand({
      SecretId: secretName
    });

    const data = await secretsManager.send(command);

    if (data.SecretString) {
      return JSON.parse(data.SecretString);
    } else {
      // Handle binary secrets
      const buff = Buffer.from(data.SecretBinary, 'base64');
      return JSON.parse(buff.toString('ascii'));
    }
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw error;
  }
}

// Usage in app.js
async function initializeApp() {
  const dbSecret = await getSecret('prod/database/credentials');
  const stripeSecret = await getSecret('prod/stripe/api-key');

  // Use secrets for configuration
  const dbConfig = {
    host: dbSecret.host,
    username: dbSecret.username,
    password: dbSecret.password,
    database: dbSecret.database
  };

  // Initialize database connection, etc.
}
```

