### Option 1: Using AWS Secrets Manager (Production Recommended)

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");
const client = new SecretsManagerClient({ region: "us-east-1" });

async function getSecret(secretName) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const data = await client.send(command);

    if (data.SecretString) {
      return JSON.parse(data.SecretString);
    }

    // For binary secrets
    const buff = new Buffer(data.SecretBinary, 'base64');
    return buff.toString('ascii');
  } catch (error) {
    console.error('Error retrieving secret:', error);
    throw error;
  }
}

// Usage in app.js
let secrets;
try {
  secrets = await getSecret("production/app-secrets");
  const stripe = require('stripe')(secrets.STRIPE_SECRET_KEY);
  // ... use secrets
} catch (error) {
  console.error('Failed to load secrets, shutting down');
  process.exit(1);
}
```

